import json, sys, textwrap
for line in open(sys.argv[1], encoding="utf-8"):
    try: rec = json.loads(line)
    except Exception: continue
    label = rec.get("label") or rec.get("agentLabel") or ""
    res = rec.get("result") or rec.get("value") or rec.get("output")
    if not isinstance(res, dict): continue
    print("=" * 78); print("###", label)
    print(textwrap.fill(res.get("summary",""), 96)); print()
    for e in res.get("edits", []):
        print("  * %s:%s" % (e.get("file"), e.get("line")))
        print(textwrap.fill("    -> " + e.get("change","")[:400], 96, subsequent_indent="       "))
    if res.get("constraints"):
        print("\n  KISITLAR:")
        for c in res["constraints"][:6]:
            print(textwrap.fill("    - " + c[:300], 96, subsequent_indent="      "))
    if res.get("risks"):
        print("\n  RISKLER:")
        for r in res["risks"][:8]:
            print(textwrap.fill("    ! " + r[:340], 96, subsequent_indent="      "))
    print()
PYEOF

